package com.jnapanam.sportszone.content.dto;import com.jnapanam.sportszone.content.model.*;import java.time.Instant;import java.util.UUID;public record ContactResponse(UUID id,String name,String email,String mobile,String subject,String message,InquiryStatus status,String adminNote,Instant createdAt,Instant resolvedAt){public static ContactResponse from(ContactInquiry c){return new ContactResponse(c.getId(),c.getName(),c.getEmail(),c.getMobile(),c.getSubject(),c.getMessage(),c.getStatus(),c.getAdminNote(),c.getCreatedAt(),c.getResolvedAt());}}
